subpage_row 实现（参考 settings_row_value 结构）：
```c
/* Generic iOS list row: icon badge + title/subtitle + optional value + arrow */
static lv_obj_t *subpage_row(lv_obj_t *card, const char *icon, uint32_t color,
                             const char *title, const char *subtitle,
                             const char *value)
{
    lv_obj_t *row = make_clean_cont(card);
    lv_obj_set_size(row, lv_pct(100), SETTING_ROW_H);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(row, 12, 0);
    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);

    /* Icon badge */
    lv_obj_t *badge = lv_obj_create(row);
    lv_obj_set_size(badge, DM(36), DM(36));
    lv_obj_set_style_radius(badge, RAD_CARD, 0);
    lv_obj_set_style_bg_color(badge, lv_color_hex(color), 0);
    lv_obj_set_style_bg_opa(badge, LV_OPA_COVER, 0);
    lv_obj_set_style_shadow_width(badge, 8, 0);
    lv_obj_set_style_shadow_color(badge, lv_color_hex(color), 0);
    lv_obj_set_style_shadow_opa(badge, LV_OPA_30, 0);
    lv_obj_set_style_border_width(badge, 0, 0);
    lv_obj_set_style_pad_all(badge, 0, 0);
    lv_obj_set_scrollbar_mode(badge, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(badge, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *ic = lv_label_create(badge);
    lv_label_set_text(ic, icon);
    lv_obj_set_style_text_font(ic, FONT_ICON, 0);
    lv_obj_set_style_text_color(ic, lv_color_hex(0xFFFFFF), 0);
    lv_obj_center(ic);

    /* Title + subtitle column */
    lv_obj_t *tcol = make_clean_cont(row);
    lv_obj_set_flex_grow(tcol, 1);
    lv_obj_set_height(tcol, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(tcol, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(tcol, 2, 0);

    lv_obj_t *tl = lv_label_create(tcol);
    lv_label_set_text(tl, title);
    lv_obj_set_style_text_font(tl, FONT_BODY, 0);
    lv_obj_set_style_text_color(tl, lv_color_hex(COL_TEXT), 0);

    if (subtitle) {
        lv_obj_t *sl = lv_label_create(tcol);
        lv_label_set_text(sl, subtitle);
        lv_obj_set_style_text_font(sl, FONT_BODY, 0);
        lv_obj_set_style_text_color(sl, lv_color_hex(COL_SEC), 0);
    }

    /* Optional value (right side) */
    if (value) {
        lv_obj_t *vl = lv_label_create(row);
        lv_label_set_text(vl, value);
        lv_obj_set_style_text_font(vl, FONT_BODY, 0);
        lv_obj_set_style_text_color(vl, lv_color_hex(COL_SEC), 0);
    }

    /* Arrow */
    lv_obj_t *arrow = lv_label_create(row);
    lv_label_set_text(arrow, LV_SYMBOL_RIGHT);
    lv_obj_set_style_text_font(arrow, FONT_BODY, 0);
    lv_obj_set_style_text_color(arrow, lv_color_hex(COL_SEC), 0);

    return row;
}
```

